  from_coordinates?: number[];
  /** Адрес куда (для travel) или адрес действия (для pickup/delivery) */
  to_address: string;
  /** Тип точки куда (для travel) или тип точки действия (для pickup/delivery) */
  to_address_type: RouteSegmentDtoToAddressType;
  /** Координаты куда (для всех типов сегментов) [lat, lng] */
  to_coordinates: number[];
  /** Время на сегмент в формате "Xч Yмин" */
  time: string;
  /** Расстояние сегмента (км), только для travel */
